export function main(input) {
  if (input.next_cursor) {
    throw new Error('日報が 200 件を超えました。集計の範囲を分けてください');
  }
  var map = {};
  for (var i = 0; i < input.items.length; i++) {
    var it = input.items[i];
    var rep = String(it.data.rep || '（担当者未設定）');
    if (!map[rep]) map[rep] = { rep: rep, visits: 0, prospect: 0 };
    map[rep].visits += Number(it.data.visits || 0);
    map[rep].prospect += Number(it.data.prospect || 0);
  }
  var rows = Object.keys(map).sort().map(function (k) {
    return { week_start: input.week_start, rep: map[k].rep, visits: map[k].visits, prospect: map[k].prospect };
  });
  var lines = rows.map(function (r) {
    return '- ' + r.rep + ': 訪問 ' + r.visits + ' 件・見込み額 ' + r.prospect + ' 円';
  });
  return { rows: rows, summary_text: lines.length ? lines.join('\n') : '（対象の日報はありません）' };
}

export function main(input) {
  const groups = input.groups || [];
  const rows = groups.map((g) => {
    const src = Object.assign({}, g, g.values || {}, g.aggregates || {}, g.metrics || {});
    const keyObj = g.group || g.key || g.keys || {};
    const rep = String(src.rep ?? keyObj.rep ?? '');
    const pickNum = (re) => {
      for (const k of Object.keys(src)) {
        if (re.test(k) && typeof src[k] === 'number') return src[k];
      }
      return 0;
    };
    return { rep, visits: pickNum(/visit/i), prospect: pickNum(/prospect/i) };
  });
  rows.sort((a, b) => a.rep.localeCompare(b.rep, 'ja'));
  const week_start = input.start;
  const out = rows.map((r) => ({ week_start, rep: r.rep, visits: r.visits, prospect: r.prospect }));
  const total_visits = rows.reduce((s, r) => s + r.visits, 0);
  const total_prospect = rows.reduce((s, r) => s + r.prospect, 0);
  const table_text = ['担当者 / 訪問件数 / 見込み額']
    .concat(rows.map((r) => r.rep + ' / ' + r.visits + '件 / ' + r.prospect + '円'))
    .concat(['合計 / ' + total_visits + '件 / ' + total_prospect + '円'])
    .join('\n');
  return { rows: out, table_text, total_visits, total_prospect };
}

export function main(input) {
  const m = {};
  for (const it of input.items) {
    const d = it.data || {};
    const rep = String(d.rep ?? '');
    if (!m[rep]) m[rep] = { rep: rep, visits: 0, prospect: 0 };
    m[rep].visits += Number(d.visits ?? 0);
    m[rep].prospect += Number(d.prospect ?? 0);
  }
  const rows = Object.values(m);
  const text = rows.map(r => '- ' + r.rep + ': 訪問 ' + r.visits + ' 件・見込み額 ' + r.prospect + ' 円').join('\n');
  return { rows: rows, text: text || '（この週の日報はありません）' };
}

function main(input) {
 const items = input.items || [];
 const map = {};
 for (const it of items) {
 const d = it.data || {};
 const rep = d.rep || '(担当者なし)';
 if (!map[rep]) map[rep] = { week_start: input.week_start, rep: rep, visits: 0, prospect: 0 };
 map[rep].visits += Number(d.visits || 0);
