export function main(input) {
  const rows = [];
  const lines = [];
  for (const g of input.groups ?? []) {
    const region = g.region ?? g.key?.region ?? g.group?.region ?? null;
    const total = g.sum_amount ?? g.sum?.amount ?? g.sum ?? null;
    const deals = g.count ?? g.deals ?? null;
