function main(input) {
  const groups = Array.isArray(input.groups) ? input.groups : [];
  const isNum = (v) => typeof v === 'number';
  const rows = groups.map((g) => {
    let total = null;
    let deals = null;
    for (const k of Object.keys(g)) {
      if (k === 'region') continue;
      const v = g[k];
      if (/count|件数|deal/i.test(k)) deals = v;
      else if (/sum|amount|total|合計|金額/i.test(k)) total = v;
    }
    return { week_start: input.week_start, region: g.region ?? null, total: total, deals: deals };
  });
  const fmt = (v) => (isNum(v) ? String(v) : '伏せられています');
  const lines = rows.map((r) => r.region + ': 合計 ' + fmt(r.total) + ' / 件数 ' + fmt(r.deals));
  return { rows: rows, summary: '対象週の開始日: ' + input.week_start + '\n' + lines.join('\n') };
}

