    due_on: it.data && it.data.due_on
  })).filter((r) => r.due_on && r.due_on < input.date);
  rows.sort((a, b) => (a.due_on < b.due_on ? -1 : a.due_on > b.due_on ? 1 : 0));
  const lines = ['# 延滞一覧 ' + input.date, ''];
  if (rows.length === 0) {
    lines.push('延滞はありません。');
  } else {
    lines.push('| 管理番号 | 借りた人 | 返却予定日 |');
    lines.push('|---|---|---|');
    for (const r of rows) {
      lines.push('| ' + esc(r.code) + ' | ' + esc(r.borrower) + ' | ' + esc(r.due_on) + ' |');
    }
    lines.push('');
    lines.push('件数: ' + rows.length + ' 件');
  }
  return { markdown: lines.join('\n') + '\n' };
}

function main(input) {
  const items = input.items || [];
  const esc = (v) => (v === null || v === undefined ? "" : String(v).split("\n").join(" "));
  const lines = items.map((r) => `| ${esc(r.data.code)} | ${esc(r.data.borrower)} | ${esc(r.data.due_on)} |`);
  const md = [`# 延滞一覧（${input.date}）`, "", `返却予定日を過ぎ、返却日が未入力の貸出は ${items.length} 件です。`, "", "| 管理番号 | 借りた人 | 返却予定日 |", "|---|---|---|", ...lines].join("\n");
  return { markdown: md + "\n" };
}

export function main(input) {
  const items = input.items ?? [];
  const context = items.map((it, i) => `[${i + 1}] 番号: ${it.data.faq_no ?? ''}\nQ: ${it.data.question ?? ''}\nA: ${it.data.answer ?? ''}`).join('\n\n');
  const source = items.map(it => it.data.faq_no ?? '').filter(x => x !== '').join(', ');
  return { context, source };
}

