export function main(input) {
  const n = Number(input.responses);
  const p = Number(input.promoters);
  const d = Number(input.detractors);
  if (!n) throw new Error("回答が 1 件もありません");
  const raw = (p - d) / n * 100;
  const nps = Math.sign(raw) * Math.round(Math.abs(raw));
  return { responses: n, promoters: p, detractors: d, nps: nps };
}

function main(input) {
  const r = input.items && input.items[0];
  if (!r) throw new Error('集計できる行がありません');
  const responses = Number(r.responses);
  const promoters = Number(r.promoters);
  const detractors = Number(r.detractors);
  if (!responses) throw new Error('回答が 0 件のため NPS を出せません');
  const raw = (promoters - detractors) / responses * 100;
  const nps = raw < 0 ? -Math.floor(-raw + 0.5) : Math.floor(raw + 0.5);
  return { responses: responses, promoters: promoters, detractors: detractors, nps: nps };
}

function main(input) {
  const row = (input && input.items && input.items[0]) || {};
  const responses = Number(row.responses || 0);
  const promoters = Number(row.promoters || 0);
  const detractors = Number(row.detractors || 0);
  const nps = responses > 0 ? Math.round((promoters - detractors) / responses * 100) : 0;
  return { responses: responses, promoters: promoters, detractors: detractors, nps: nps };
}
